INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'cape-town-weighs-summer-water-restrictions-2026-09-16',
  'Cape Town weighs summer water restrictions as dams sit near 75.5%',
  'Utilities', '2026-09-16', 'Cape Argus (IOL)', 'https://iol.co.za/capeargus/news/2026-09-16-cape-town-considers-water-restrictions-as-dam-levels-fall-to-755/',
  'The City says its Water Restrictions Committee is considering precautionary restrictions before summer, with combined dam storage at about 75.5% and no restrictions in force yet.',
  'The City of Cape Town says its Water Restrictions Committee is looking at whether to bring in water restrictions ahead of summer as a precaution. Nothing has been imposed yet. The committee is weighing how full the dams are, how much water the city is expected to use, what summer consumption usually looks like and what the rainfall forecasts say.

The combined Cape Town dams stood at about 75.5%, compared with 92.4% at the same point last year, according to the City''s latest update. Residents used roughly 855 million litres a day in the most recent period, which is a little below the 860 million litre daily goal set for winter.

Zahid Badroodien, who holds the water and sanitation portfolio on the mayoral committee, said the current water outlook does not point to an immediate threat to supply, but that the City is keeping a close eye on dam levels and demand patterns so it is ready for a range of scenarios. A drier and hotter summer is expected.

Residents are asked to keep using water wisely, since the City describes Cape Town as a water-scarce city. Saving tips are listed at capetown.gov.za/savewater.',
  NULL, NULL, NULL,
  '["https://iol.co.za/capeargus/news/2026-09-16-cape-town-considers-water-restrictions-as-dam-levels-fall-to-755/", "https://www.politicsweb.co.za/news/dam-levels-at-755-cape-town", "https://www.timeout.com/cape-town/news/dam-levels-and-water-restrictions-still-a-concern-despite-stormy-weather-ahead-091526"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'city-pools-open-daily-september-school-holidays-2026-09-19',
  'Most City pools open daily for the September school holidays',
  'Community', '2026-09-19', 'City of Cape Town', 'https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/City-pools-ready-to-welcome-families-during-September-school-holidays?category=Media%20releases',
  'Public pools run by the City open every day from 23 September to 5 October, while five pools stay shut for maintenance or redevelopment.',
  'During the spring school holidays, from 23 September to 5 October, you will find most City-run swimming pools open every day. Opening hours over that period are 10:00 to 17:00.

After the holidays the pools move to a shorter roster that runs until 1 December. On Wednesdays to Fridays they open from 13:00 to 17:00, and on Saturdays and Sundays from 10:00 to 17:00.

Five pools will not be available. Westridge, Bellville Central, Mnandi and Athlone are shut while maintenance is done, and the City says they will reopen in phases once the work, quality assessments and safety checks are complete. No reopening dates have been given. Vulindela pool stays closed for the whole summer season while plans for its redesign move forward.

Community services and health mayoral committee member Francine Higham asked visitors to follow the pool rules, listen to the lifeguards and keep a close watch on children at all times. The City is also recruiting seasonal lifeguards ahead of the busy festive period.',
  NULL, NULL, NULL,
  '["https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/City-pools-ready-to-welcome-families-during-September-school-holidays?category=Media%20releases", "https://smilefm.co.za/cape-town-pools-open-daily-during-september-school-holidays/"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'construction-starts-tutu-memorial-park-milnerton-2026-09-18',
  'Construction starts on Tutu Memorial Park in Milnerton',
  'Community', '2026-09-18', 'EWN', 'https://www.ewn.co.za/2026/09/18/local-performers-artists-set-to-benefit-from-under-construction-desmond-tutu-memorial-park',
  'Building work has begun to turn Lupin Crescent Park in Milnerton into the Tutu Memorial Park, with an amphitheatre, children''s play area and memorial garden.',
  'Work has started on transforming Lupin Crescent Park in Milnerton into the Tutu Memorial Park, in honour of Archbishop Desmond Tutu. Ground was broken on Thursday, 17 September, at a launch event with Mama Leah Tutu, Mayor Geordin Hill-Lewis and Dr Mamphela Ramphele.

According to reports on the launch, the redesigned park will have an amphitheatre for community performances, a children''s play area, a memorial garden and a dog park. There will also be public artworks about the archbishop''s life and legacy, along with new parking, lighting, pathways and accessibility upgrades, plus landscaping and irrigation.

Two local groups, the Royal Ascot homeowners association and the Milnerton ratepayers body, suggested the project, and nobody objected. The mayor said the park sits close to the Tutu family home and reflects the archbishop''s well-known affection for children.

The City expects the building work to take about six months. No cost was given in the coverage we reviewed.',
  NULL, NULL, NULL,
  '["https://www.ewn.co.za/2026/09/18/local-performers-artists-set-to-benefit-from-under-construction-desmond-tutu-memorial-park", "https://www.capetownetc.com/news/tutu-memorial-park-construction-milnerton/", "https://tabletalk.co.za/table-talk/news/2026-09-18-watch-milnertons-tutu-memorial-park-project-gets-under-way/"]',
  'agent'
);

INSERT OR IGNORE INTO news (
  slug, title, category, published_date, source_name, source_url,
  summary, body, image_url, image_credit, image_source, verification_json, source
) VALUES (
  'city-lists-top-five-scams-targeting-residents-2026-09-18',
  'City lists the five scams most often targeting Cape Town residents',
  'Community', '2026-09-18', 'City of Cape Town', 'https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/Warning-Here-are-the-Top-Five-scams-hurting-residents?category=Media%20releases',
  'The City has warned residents about fake disconnection threats, housing and job offers, traffic-fine demands and bogus parking fees, and says how to check what is genuine.',
  'The City of Cape Town has published a list of the five scams it says are hurting residents most, and is urging people to stop and verify before paying anyone.

The first is a WhatsApp message claiming your water or electricity account is in arrears and threatening disconnection unless you pay straight away. According to the City, disconnection warnings are never sent over WhatsApp or social media. The other four are offers of state-subsidised housing in return for money, demands to pay supposed traffic fines by SMS, email or WhatsApp, requests to pay parking fees to someone who is not an official marshal, and fake job offers spread on WhatsApp or flyers.

According to the City, there is no fee to be placed on the Housing Needs Register, and it does not charge for job opportunities. Parking is paid only to authorised marshals at the time of parking. Residents should use official City payment channels and never personal bank accounts.

The City lists its call centre as 0860 103 089. Anyone who has been targeted can also report it at the nearest police station.',
  NULL, NULL, NULL,
  '["https://web1.capetown.gov.za/web1/newsandnotices/Home/Release/Warning-Here-are-the-Top-Five-scams-hurting-residents?category=Media%20releases", "https://iol.co.za/news/crime-and-courts/2026-09-18-cape-town-scam-alert-top-five-scams-targeting-residents/", "https://www.capetownetc.com/news/these-are-the-top-5-scams-targeting-cape-town-residents/"]',
  'agent'
);
